// PDF page → app screen number mapping (derived from WORLDS ranges).
// Screens 1–10 cover PDF pp. 1–15, 11–27 → pp. 16–33, 28–40 → pp. 34–46,
// 41–46 → pp. 47–52, 47–54 → pp. 53–60, 55–58 → pp. 61–64, 59–76 → pp. 65–76,
// 77–106 → pp. 77–106 (Vahvuusmittari, 1:1).
const RANGES: Array<[number, number, number, number]> = [
  [ 1, 10,  1, 15],
  [11, 27, 16, 33],
  [28, 40, 34, 46],
  [41, 46, 47, 52],
  [47, 54, 53, 60],
  [55, 58, 61, 64],
  [59, 76, 65, 76],
  [77,106, 77,106],
];

export function pagesForScreen(screenNr: number): number[] {
  for (const [sStart, sEnd, pStart, pEnd] of RANGES) {
    if (screenNr < sStart || screenNr > sEnd) continue;
    const nScreens = sEnd - sStart + 1;
    const nPages = pEnd - pStart + 1;
    if (nScreens === nPages) return [pStart + (screenNr - sStart)];
    // proportional bucket
    const idx = screenNr - sStart;
    const pFrom = pStart + Math.floor((idx * nPages) / nScreens);
    const pTo = pStart + Math.max(pFrom, Math.floor(((idx + 1) * nPages) / nScreens) - 1);
    const out: number[] = [];
    for (let p = pFrom; p <= pTo; p++) out.push(p);
    return out;
  }
  return [];
}

export interface ScreenContentLine {
  key: string;
  section: string | null;
  text: string;
}

/** Return every workbook line whose PDF page overlaps the given app screen,
 *  rendered in the selected language (falls back FI ← SV ← EN when missing). */
export function getScreenContent(screenNr: number, language: Language): ScreenContentLine[] {
  const pages = new Set(pagesForScreen(screenNr));
  if (!pages.size) return [];
  const out: ScreenContentLine[] = [];
  for (const [key, entry] of Object.entries(SCREEN_STRINGS)) {
    if (!entry.pages.some((p) => pages.has(p))) continue;
    const primary = entry[language];
    const text = primary ?? entry.fi ?? entry.sv ?? entry.en;
    if (!text) continue;
    out.push({ key, section: entry.section, text });
  }
  return out;
}

/** Look up a single string by its stable workbook key (e.g. "m1_1"). */
export function getString(key: string, language: Language): string | null {
  const entry = SCREEN_STRINGS[key];
  if (!entry) return null;
  return entry[language] ?? entry.fi ?? entry.sv ?? entry.en ?? null;
}
